-- Optional reference schema for the Professional Network tables. server/collaboration.js creates these tables and safely adds profile columns on startup.
CREATE TABLE IF NOT EXISTS mentorship_requests (id TEXT PRIMARY KEY, student_id TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, mentor_id TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, career_goal TEXT NOT NULL DEFAULT '', message TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','declined','completed')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK(student_id != mentor_id));
CREATE TABLE IF NOT EXISTS professional_opportunities (id TEXT PRIMARY KEY, posted_by TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, title TEXT NOT NULL, organization TEXT NOT NULL DEFAULT '', opportunity_type TEXT NOT NULL DEFAULT 'job', location TEXT NOT NULL DEFAULT '', description TEXT NOT NULL DEFAULT '', skills TEXT NOT NULL DEFAULT '', deadline TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS opportunity_applications (id TEXT PRIMARY KEY, opportunity_id TEXT NOT NULL REFERENCES professional_opportunities(id) ON DELETE CASCADE, applicant_id TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, message TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'submitted', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(opportunity_id,applicant_id));
CREATE TABLE IF NOT EXISTS professional_events (id TEXT PRIMARY KEY, created_by TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', event_date TEXT NOT NULL, location TEXT NOT NULL DEFAULT '', event_type TEXT NOT NULL DEFAULT 'networking', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS professional_event_registrations (event_id TEXT NOT NULL REFERENCES professional_events(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(event_id,user_id));
